import {CODES} from './engine.mjs';
const POLICIES={
 1997:{title:'Work RVUs reweighted',bullets:['The five-year review revised physician-work RVUs for office visits, including increases for 99213 and 99214.','A separate budget-neutrality factor of 0.917 was applied to work RVUs. The published RVUs below are before that adjustment.'],component:'work',componentLabel:'Published work RVUs',url:'https://www.govinfo.gov/content/pkg/FR-1996-11-22/pdf/96-29558.pdf'},
 1999:{title:'Practice-expense RVUs moved to a resource basis',bullets:['Practice-expense RVUs began shifting from historical charges to the resources used to provide care.','The 1999 blend was 75% charge-based and 25% resource-based. The transition reached 100% resource-based in 2002.'],component:'pe',componentLabel:'Office practice-expense RVUs',url:'https://www.cms.gov/Regulations-and-Guidance/Guidance/Transmittals/Downloads/R1769B3.pdf'},
 2007:{title:'Office-visit work RVUs reweighted upward',bullets:['The five-year review increased work RVUs for established office visits, including 99213 and 99214.','A separate budget-neutrality adjustment multiplied work RVUs by 0.8994; it did not reduce practice-expense or malpractice RVUs. The published RVUs below are before that adjustment.'],component:'work',componentLabel:'Published work RVUs',url:'https://www.cms.gov/newsroom/press-releases/medicare-announces-final-rule-setting-physician-payment-rates-and-policies-2007'},
 2021:{title:'Office E/M values and code selection changed',bullets:['Office/outpatient E/M services were revalued, with higher work RVUs for 99213 and 99214.','Visit level could be selected using medical decision-making or total practitioner time on the service date. History and examination no longer determined the level.'],component:'work',componentLabel:'Published work RVUs',url:'https://www.cms.gov/sites/default/files/2022-01/Physician_Fee_Schedule__PFS__Payment_for_OfficeOutpatient_Evaluation_and_Management__EM__Visits.pdf'},
 2024:{title:'G2211 became separately payable',bullets:['G2211 was added as a separately payable complexity add-on to new and established office/outpatient E/M visits. It had its own fixed RVUs, so it added the same amount at every visit level.','It recognizes ongoing care relationships: being the continuing focal point for care, or managing a serious or complex condition over time.'],url:'https://www.cms.gov/files/document/mm13473-how-use-office-and-outpatient-evaluation-and-management-visit-complexity-add-code-g2211.pdf'},
 2025:{title:'Conversion factor cut for the fourth year in a row',bullets:['The conversion factor fell in 2022, 2023, 2024 and 2025: from 34.8931 per RVU in 2021 to 32.3465 in 2025, a 7.3% cut. Office E/M RVUs barely changed, so visit fees fell with it.','Temporary increases set by Congress for 2021–2024 offset part of the cuts; none carried into 2025. Budget-neutrality offsets for the 2021 E/M revaluation and for G2211 also lowered the conversion factor.'],url:'https://www.cms.gov/files/document/cms-1807-f.pdf'},
 2026:{title:'Conversion factor rose; office practice-expense values increased',bullets:['The conversion factor rose 3.26% for non-QPs and 3.77% for QPs, including a one-year 2.5% increase set by statute. QP and non-QP conversion factors differed for the first time.','CMS recognized greater indirect practice costs for office-based practitioners than for facility-based ones, raising office practice-expense RVUs. Office E/M visits were exempt from the new 2.5% efficiency cut to work RVUs.'],component:'pe',componentLabel:'Office practice-expense RVUs',url:'https://www.cms.gov/newsroom/fact-sheets/calendar-year-cy-2026-medicare-physician-fee-schedule-final-rule-cms-1832-f'},
 2027:{title:'B1 and B2 replaced G2211',bullets:['G2211 was replaced by complexity modifiers appended to the base E/M visit. Instead of a fixed add-on, the uplift now scales with the visit level.','B1 adds 16% of the base visit’s total RVUs, its full fee. B2 adds 32% for clinicians in an MSSP or LEAD ACO. B2 depends on ACO participation, not on QP status.'],url:'https://public-inspection.federalregister.gov/2026-22743.pdf'}
};
export function policyFor(data,state,year){const policy=POLICIES[year];if(!policy)return null;const component=policy.component;const eligible=CODES.filter(code=>state.mix[code]>0).map(code=>({code,before:data.rvus.find(r=>r.year===year-1&&r.code===code),after:data.rvus.find(r=>r.year===year&&r.code===code)})).filter(r=>r.before&&r.after);const examples=component?eligible.filter(r=>r.before[component]!==r.after[component]).sort((a,b)=>state.mix[b.code]-state.mix[a.code]||a.code.localeCompare(b.code)).slice(0,2).sort((a,b)=>a.code.localeCompare(b.code)).map(r=>({code:r.code,before:r.before[component],after:r.after[component],sourceId:r.after.source_id,sourcePage:r.after.source_page})):[];return {...policy,year,examples};}
